import "aos/dist/aos.css";
import {
    FaBalanceScale,
    FaBriefcase,
    FaFileContract,
    FaGavel,
    FaWhatsapp,
} from "react-icons/fa";

function LawFirm() {
    //-----------------------STATE VIEWS-----------------------//
    const lawServices = [
        {
            title: "Corporate & Business Law",
            description:
                "Legal assistance for business entities, including company establishment, licensing, regulatory compliance, and corporate governance.",
            icon: FaBriefcase,
        },
        {
            title: "Legal Consultation",
            description:
                "Professional legal consultation services providing analysis, legal opinions, and strategic solutions to legal matters.",
            icon: FaBalanceScale,
        },
        {
            title: "Contract Drafting & Review",
            description:
                "Preparation and review of business contracts to ensure legal protection and clarity of rights and obligations of the parties involved.",
            icon: FaFileContract,
        },
        {
            title: "Litigation & Dispute Resolution",
            description:
                "Legal assistance and representation in dispute resolution through litigation or alternative dispute resolution methods.",
            icon: FaGavel,
        },
    ];

    const WA_NUMBER = "6281213094426";

    //------------------------FUNCTIONS------------------------//
    const getWaLink = (serviceName: string) => {
        const message = `Hello Regarde,%0AI would like to consult regarding the ${serviceName} service.%0APlease provide further information. Thank you.`;
        return `https://wa.me/${WA_NUMBER}?text=${message}`;
    };
    //------------------------FUNCTIONS------------------------//

    return (
        <div className="pt-24">
            {/* LAW FIRM DETAIL */}
            <section className="pb-24 bg-white" data-aos="zoom-out">
                <div className="w-11/12 md:w-8/12 mx-auto text-center">

                    {/* ICON */}
                    <div className="flex justify-center mb-6">
                        <div className="w-20 h-20 rounded-full bg-sky-100 flex items-center justify-center">
                            <FaBalanceScale className="text-sky-700 text-4xl" />
                        </div>
                    </div>

                    {/* TITLE */}
                    <h2 className="text-4xl font-black text-sky-900 mb-4">
                        Law Firm
                    </h2>

                    {/* DESCRIPTION */}
                    <p className="text-gray-600 max-w-2xl mx-auto mb-14">
                        Professional legal services to provide certainty,
                        protection, and the right legal solutions for individuals
                        and corporations.
                    </p>

                    {/* SUB SERVICES */}
                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-8 text-left">
                        {lawServices.map((service, i) => {
                            const Icon = service.icon;
                            return (
                                <div
                                    key={i}
                                    data-aos="fade-up"
                                    data-aos-delay={i * 100}
                                    className="bg-white rounded-xl border border-gray-200 p-6 hover:shadow-md transition flex flex-col"
                                >
                                    {/* CONTENT */}
                                    <div className="flex items-start gap-4">
                                        <div className="text-sky-600 text-2xl mt-1">
                                            <Icon />
                                        </div>
                                        <div>
                                            <h3 className="font-semibold text-sky-900">
                                                {service.title}
                                            </h3>
                                            <p className="text-sm text-gray-600 mt-1">
                                                {service.description}
                                            </p>
                                        </div>
                                    </div>

                                    {/* WA BUTTON */}
                                    <a
                                        href={getWaLink(service.title)}
                                        target="_blank"
                                        rel="noopener noreferrer"
                                        className="mt-auto self-end w-10 h-10 rounded-full bg-green-600 text-white flex items-center justify-center hover:bg-green-700 transition"
                                        aria-label="Chat via WhatsApp"
                                    >
                                        <FaWhatsapp className="text-lg" />
                                    </a>
                                </div>
                            );
                        })}
                    </div>
                </div>
            </section>
        </div>
    );
}

export default LawFirm;
